export const MENAGERIE_ABILITIES=MENAGERIE_FAMILIES.map(f=>f.ability);
export function installMenagerie(data){
 if(data.species.some(s=>s.approvedMenagerie))return;
 data.species.push(...MENAGERIE_SPECIES);data.moves.push(...MENAGERIE_MOVES);
 const coverage=[['FIGHTING','ROCK','ICE'],['FIGHTING','POISON','GROUND'],['DARK','GROUND','GRASS'],['ICE','PSYCHIC'],['PSYCHIC','FIGHTING','DRAGON'],['FIRE','GROUND'],['FAIRY','PSYCHIC'],['PSYCHIC','ICE'],['GROUND','STEEL'],['GROUND','ROCK']];
 for(const [index,f] of MENAGERIE_FAMILIES.entries())for(const id of f.ids){
  const species=MENAGERIE_SPECIES.find(s=>s.id===id),final=id===f.ids.at(-1),schedule=[...f.schedule,...(final?[[f.ids.length>1?0:f.learnAt,f.signature]]:[])];
  const category=species.growth_percent.attack>=species.growth_percent.sp_attack?'PHYSICAL':'SPECIAL';
  const types=coverage[index],pool=data.moves.filter(m=>m.power>0&&m.power<=65&&m.category===category&&!species.types.includes(m.type_id)&&types.includes(m.type_id)&&!m.signature_owner_family);
  const cover=pool.sort((a,b)=>types.indexOf(a.type_id)-types.indexOf(b.type_id)||Math.abs(a.power-50)-Math.abs(b.power-50)||a.id-b.id)[0];
  if(!cover)throw Error('Missing coverage for '+species.name);schedule.push([16,cover.id]);
  if(species.types.includes('FAIRY')&&category==='PHYSICAL')schedule.push([22,337],[30,346]);
  const unique=new Map();for(const [level,move_id] of schedule){const m=data.moves.find(m=>m.id===move_id);if(!m?.category||m.signature_owner_family&&m.signature_owner_family!==species.family_id)continue;unique.set(move_id,Math.min(level,unique.get(move_id)??Infinity));}
  const rows=[...unique].map(([move_id,level])=>({species_id:id,level,move_id,name:data.moves.find(m=>m.id===move_id).name,method:'LEVEL_UP',expansion:true,identity:true,identity_core:true,approvedMenagerie:true})).sort((a,b)=>a.level-b.level||a.move_id-b.move_id);
  data.learnsets.push(...rows);data.authoredLearnsets?.push(...rows.map(r=>({...r})));data.assets.push({id,source:'art-source/menagerie/'+id+'.webp',runtime:'assets/'+id+'.webp'});
 }
}
